function maxMeetings(intervals) {
  if (intervals.length === 0) return 0;
  const sorted = [...intervals].sort(function byStart(left, right) {
    return left[0] - right[0];
  });
  let count = 1;
  let end = sorted[0][1];
  for (let index = 1; index < sorted.length; index += 1) {
    if (sorted[index][0] >= end) {
      count += 1;
      end = sorted[index][1];
    }
  }
  return count;
}
